const b = $input.first().json.body || $input.first().json;
return [{ json: {
  query: b.query || '',
  user_role: b.user_role || 'general',
  session_id: b.session_id || new Date().toISOString(),
  timestamp: new Date().toISOString()
}}];

const i = $input.first().json;
const body = {
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  temperature: 0.1,
  messages: [
    {
      role: 'system',
      content: 'You are a query understanding agent for TomTom internal knowledge system. Given a user query classify and rewrite for semantic search. Return ONLY valid JSON with exactly these keys: product_area (Maps|Routing|NavSDK|Traffic|AI_Agent|General), feature (string or null), audience (sales|developer|support|CS|general), intent (pre-sales|technical-debug|compliance-check|onboarding|general), rewritten_query (string optimised for vector search).'
    },
    {
      role: 'user',
      content: 'Role: ' + i.user_role + '\nQuery: ' + i.query
    }
  ]
};
return [{ json: { ...i, _body: JSON.stringify(body) } }];

const i = $input.first().json;
let p;
try {
  p = JSON.parse(i.choices[0].message.content);
} catch(e) {
  p = { product_area: 'General', feature: null, audience: 'general', intent: 'general', rewritten_query: i.query };
}
return [{ json: {
  query: i.query,
  user_role: i.user_role,
  session_id: i.session_id,
  timestamp: i.timestamp,
  product_area: p.product_area || 'General',
  feature: p.feature || null,
  audience: p.audience || 'general',
  intent: p.intent || 'general',
  rewritten_query: p.rewritten_query || i.query
}}];

const i = $input.first().json;
const vec = i.data[0].embedding;
return [{ json: { ...i, _embedding: vec, _body: JSON.stringify({ vector: vec, topK: 5, includeMetadata: true, includeValues: false }) } }];

const i = $input.first().json;
const matches = i.matches || [];
const chunks = matches.map((m, idx) => ({
  rank: idx + 1,
  score: m.score,
  title: m.metadata && m.metadata.title ? m.metadata.title : 'Unknown',
  content: m.metadata && m.metadata.content ? m.metadata.content : (m.metadata && m.metadata.text ? m.metadata.text : ''),
  product_area: m.metadata && m.metadata.product_area ? m.metadata.product_area : 'General',
  status: m.metadata && m.metadata.status ? m.metadata.status : 'approved',
  reliability: m.metadata && m.metadata.reliability_score ? m.metadata.reliability_score : 0.8
}));
const chunks_formatted = chunks.map(c => '[' + c.rank + '] ' + c.title + ' (score:' + c.score.toFixed(2) + ', status:' + c.status + ')\n' + c.content).join('\n---\n');
return [{ json: {
  ...i,
  retrieved_chunks: chunks,
  chunks_formatted: chunks_formatted,
  chunks_count: chunks.length,
  has_draft_sources: chunks.some(c => c.status === 'draft')
}}];

const i = $input.first().json;
const body = {
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  temperature: 0.0,
  messages: [
    {
      role: 'system',
      content: 'You are a confidence evaluator for TomTom knowledge retrieval. Score 0.0-1.0 how well retrieved chunks answer the query. Return ONLY valid JSON: {"confidence_score":0.0,"reasoning":"brief","has_sufficient_answer":false,"source_quality":"high|medium|low","gap_risk":"none|minor|major"}. Scoring: 0.75-1.0=direct approved answer, 0.50-0.74=partial answer, 0.00-0.49=insufficient.'
    },
    {
      role: 'user',
      content: 'Query: ' + i.rewritten_query + '\nChunks found: ' + i.chunks_count + '\n\n' + (i.chunks_formatted || 'No chunks retrieved')
    }
  ]
};
return [{ json: { ...i, _body: JSON.stringify(body) } }];

const i = $input.first().json;
let a3;
try {
  a3 = JSON.parse(i.choices[0].message.content);
} catch(e) {
  a3 = { confidence_score: 0.3, reasoning: 'parse error', has_sufficient_answer: false, source_quality: 'low', gap_risk: 'major' };
}
const label = a3.confidence_score >= 0.75 ? 'high' : a3.confidence_score >= 0.5 ? 'medium' : 'low';
return [{ json: {
  ...i,
  confidence_score: a3.confidence_score,
  confidence_label: label,
  confidence_reasoning: a3.reasoning,
  has_sufficient_answer: a3.has_sufficient_answer,
  source_quality: a3.source_quality,
  gap_risk: a3.gap_risk
}}];

const i = $input.first().json;
const body = {
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  temperature: 0.2,
  messages: [
    {
      role: 'system',
      content: 'You are TomTom internal product knowledge assistant. Answer using ONLY provided context. Never invent facts. Adjust language for user role: sales=business language, developer=technical language. If any source has status draft add a warning. Return ONLY valid JSON: {"answer":"full answer with source refs inline","sources":[{"title":"string","product_area":"string","status":"string"}],"confidence_label":"high|medium","has_draft_sources":false,"draft_warning":null}'
    },
    {
      role: 'user',
      content: 'Role: ' + i.user_role + '\nIntent: ' + i.intent + '\nQuestion: ' + i.rewritten_query + '\n\nContext:\n' + i.chunks_formatted
    }
  ]
};
return [{ json: { ...i, _body: JSON.stringify(body) } }];

const i = $input.first().json;
let a4;
try {
  a4 = JSON.parse(i.choices[0].message.content);
} catch(e) {
  a4 = { answer: 'Error generating answer.', sources: [], confidence_label: 'low', has_draft_sources: false, draft_warning: null };
}
return [{ json: {
  ...i,
  answer: a4.answer,
  sources: a4.sources,
  final_confidence_label: a4.confidence_label,
  has_draft_sources: a4.has_draft_sources,
  draft_warning: a4.draft_warning
}}];

const i = $input.first().json;
return [{ json: {
  ...i,
  answer: 'I do not have a high-confidence answer from approved sources. A knowledge gap ticket has been created and routed to the right team. Please contact your product or sales contact directly in the meantime.',
  sources: [],
  final_confidence_label: 'low',
  has_draft_sources: false,
  draft_warning: null
}}];

const i = $input.first().json;
return [{ json: {
  ...i,
  _body: JSON.stringify({
    session_id: i.session_id,
    user_role: i.user_role,
    original_query: i.query,
    rewritten_query: i.rewritten_query,
    product_area: i.product_area,
    intent: i.intent,
    confidence_score: i.confidence_score,
    source_quality: i.source_quality,
    was_gap_created: i.confidence_score < 0.75
  })
}}];

const i = $input.first().json;
let log_id = null;
try {
  const r = Array.isArray(i) ? i[0] : i;
  log_id = r.id || null;
} catch(e) {}
return [{ json: { ...i, query_log_id: log_id } }];

const i = $input.first().json;
const body = {
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  temperature: 0.1,
  messages: [
    {
      role: 'system',
      content: 'Classify this TomTom knowledge gap and determine who should own it. Return ONLY valid JSON: {"gap_type":"SALES|PRODUCT|ENGINEERING|CONTENT|LEGAL","gap_topic":"concise topic max 10 words","priority":"low|medium|high|critical","description":"what content would resolve this gap in 1-2 sentences","suggested_owner":"Sales Enablement|Product Marketing|Engineering|Knowledge Team|Legal","routing_reason":"one sentence why this team owns it"}. Rules: SALES=pricing/pitch/positioning/competitive. PRODUCT=feature existence/roadmap/capabilities. ENGINEERING=bug or doc-behavior mismatch. CONTENT=missing/stale/contradictory docs. LEGAL=privacy/GDPR/licensing/contracts. Priority: critical=live deal blocked, high=sales or CS affected, medium=internal process, low=nice to have.'
    },
    {
      role: 'user',
      content: 'Failed query: "' + i.query + '"\nUser role: ' + i.user_role + '\nIntent: ' + i.intent + '\nProduct area: ' + i.product_area + '\nConfidence score: ' + i.confidence_score
    }
  ]
};
return [{ json: { ...i, _body: JSON.stringify(body) } }];

const i = $input.first().json;
let a6;
try {
  a6 = JSON.parse(i.choices[0].message.content);
} catch(e) {
  a6 = { gap_type: 'CONTENT', gap_topic: 'Unclassified gap', priority: 'medium', description: 'Could not auto-classify', suggested_owner: 'Knowledge Team', routing_reason: 'Default routing to knowledge team' };
}
const gap_body = JSON.stringify({
  topic: a6.gap_topic,
  gap_type: a6.gap_type,
  priority: a6.priority,
  description: a6.description,
  suggested_owner: a6.suggested_owner,
  source_query_id: i.query_log_id,
  status: 'open',
  occurrence_count: 1
});
return [{ json: {
  ...i,
  gap_type: a6.gap_type,
  gap_topic: a6.gap_topic,
  gap_priority: a6.priority,
  gap_description: a6.description,
  suggested_owner: a6.suggested_owner,
  routing_reason: a6.routing_reason,
  _gap_body: gap_body
}}];
